func:
// KOPRU: form ciktisini zincirin bekledigi bicime cevirir.
//
// Form Submit'te msg.payload su yapida gelir:
//   { data: { <PropertyName>: deger, submit: true },
//     metadata: {...}, state: "submitted" }
//
// Ders 8'de bu noktaya UC DOSYANIN BIRLESIMI geliyordu.
// Simdi tek bir metin alanindan geliyor -- gerisi ayni.

const veri = (msg.payload && msg.payload.data) || {};
const notlar = (veri.notlar || "").trim();

if (!notlar) {
  node.status({ fill: "red", shape: "ring", text: "bos form" });
  node.error("Form bos gonderildi", msg);
  return null;
}

msg.payload = notlar;
node.status({ fill: "blue", shape: "dot", text: notlar.length + " karakter alindi" });
return msg;

// Ajan cevabi { response: "..." } yapisinda gelir (outputSchema yoksa).
// Metni hem dosyaya yazmak hem sonraki adimlara tasimak icin ayiriyoruz.

msg.fsMetni = msg.payload.response || msg.payload;
msg.payload = msg.fsMetni;   // file dugumu METIN bekler
msg.filename = "/internal-storage-files/cikti/01-FS.md";

node.status({ fill: "green", shape: "dot", text: "FS yazildi" });
return msg;

// Bu dugum iki yoldan gecilir:
//   1. Ilk gelis  -> FS'ten gelir, msg.tur = 0
//   2. Geri donus -> Reviewer'dan gelir, msg.tur artmistir ve
//                    msg.bulgular doludur
//
// Ders 7'deki retry dongusunun aynisi: sayac msg uzerinde, ust sinir var.

msg.tur = (msg.tur || 0) + 1;

const NL = String.fromCharCode(10);   // kacis sorunu yasamamak icin
const fs = msg.fsMetni;
const oncekiTs = msg.tsMetni || "";
const bulgular = msg.bulgular || [];

let duzeltmeBolumu = "";
if (bulgular.length > 0) {
  const liste = bulgular
    .map(b => "- [" + (b.onem || "orta") + "] " + b.madde)
    .join(NL);

  // ONEMLI: onceki TS'in TAMAMINI geri gondermiyoruz.
  // Ilk denemede gonderdik ve platform gecidi zaman asimina ugradi
  // (OriginTimeout). Sadece bolum basliklarini gonderiyoruz; yapi
  // korunuyor ama girdi kucuk kaliyor.
  const basliklar = oncekiTs
    .split(NL)
    .filter(l => l.charAt(0) === "#")
    .join(NL);

  duzeltmeBolumu = [
    "",
    "BU BIR DUZELTME TURU (tur " + msg.tur + ").",
    "Asagidaki bulgulari giderecek sekilde belgeyi YENIDEN uret.",
    "",
    "BULGULAR:",
    liste,
    "",
    "ONCEKI BELGENIN YAPISI (sadece basliklar -- bu yapiyi koru):",
    "---",
    basliklar,
    "---",
    ""
  ].join(NL);
}

msg.payload = [
  "Asagidaki fonksiyonel sartnameden bir TEKNIK SARTNAME (TS) uret.",
  duzeltmeBolumu,
  "Kurallar:",
  "",
  "1. ABAP / SAP S4HANA hedefle.",
  "2. Kullanilacak tablolari ve alanlari acikca yaz.",
  "3. Program adi, tablo tipi, yapi adlarini naming convention'a uydur.",
  "4. Performans kisitini goz ardi etme.",
  "5. KISA TUT: en fazla 180 satir. Uzun belge uretme -- platform gecidi",
  "   uzun cevaplarda zaman asimina ugruyor.",
  "6. Ciktiyi Markdown olarak ver. Baslik yapisi:",
  "   # Teknik Sartname",
  "   ## 1. Genel Bakis",
  "   ## 2. Veri Kaynaklari",
  "   ## 3. Program Yapisi",
  "   ## 4. Algoritma",
  "   ## 5. Yetki ve Zamanlama",
  "   ## 6. Test Senaryolari",
  "",
  "FONKSIYONEL SARTNAME:",
  "---",
  fs,
  "---"
].join(NL);

node.status({ fill: "blue", shape: "dot", text: "TS uretiliyor (tur " + msg.tur + ")" });
return msg;

// Her tur ayri dosyaya yazilir: 02-TS-tur1.md, 02-TS-tur2.md ...
// Boylece "ikinci turda ne degisti?" sorusu somut olarak cevaplanabilir.

msg.tsMetni = msg.payload.response || msg.payload;
msg.payload = msg.tsMetni;
msg.filename = `/internal-storage-files/cikti/02-TS-tur${msg.tur}.md`;

node.status({ fill: "green", shape: "dot", text: `TS tur ${msg.tur} yazildi` });
return msg;

// Reviewer'in cevabi outputSchema ile YAPILANDIRILMIS gelir:
//   { onay: boolean, bulgular: [{madde, onem}], ozet: string }
// Bu yuzden switch dugumu metin icinde arama yapmak zorunda kalmaz.

msg.tsMetni = msg.payload.response || msg.payload;

msg.payload = `Asagidaki teknik sartnameyi bir SAP kidemli gelistiricisi
gozuyle incele.

Sorulacak sorular:
- Fonksiyonel sartnamedeki her kural teknik olarak karsilanmis mi?
- Tablo ve alan secimleri dogru mu?
- Performans kisiti dikkate alinmis mi?
- Gelistirici bu belgeyle kod yazmaya baslayabilir mi?

Eksik veya hatali bir sey bulursan onay verme; bulgulari maddeler halinde yaz.
EN FAZLA 5 BULGU yaz -- sadece gelistirmeyi engelleyecek kadar onemli
olanlari. Kucuk eksikleri gormezden gel.
Belge yeterliyse onay ver.

FONKSIYONEL SARTNAME:
---
${msg.fsMetni}
---

TEKNIK SARTNAME:
---
${msg.tsMetni}
---`;

node.status({ fill: "blue", shape: "dot", text: "inceleniyor..." });
return msg;

// Reviewer ciktisini oku ve karari msg'ye yaz.
// switch dugumu bundan sonra sadece msg.karar alanina bakar.

const r = msg.payload;           // outputSchema sayesinde nesne
const ENUST_TUR = 2;             // duzeltme turu ust siniri

msg.onay = r.onay === true;
msg.bulgular = r.bulgular || [];
msg.ozet = r.ozet || "";

if (msg.onay) {
  msg.karar = "gelistir";
  node.status({ fill: "green", shape: "dot", text: `onaylandi (tur ${msg.tur})` });
} else if (msg.tur < ENUST_TUR) {
  msg.karar = "duzelt";
  node.status({ fill: "yellow", shape: "ring",
                text: `duzeltme (${msg.bulgular.length} bulgu)` });
} else {
  msg.karar = "mudahale";
  node.status({ fill: "red", shape: "dot", text: "tur hakki bitti" });
}

return msg;

msg.payload = `Asagidaki teknik sartnameye gore ABAP kodunu yaz.

Kurallar:
1. Calisir, eksiksiz bir program yaz -- sozde kod degil.
2. Naming convention'a uy.
3. Kodu yorumla; her ana blogun ne yaptigini kisaca acikla.
4. Sadece kodu dondur, aciklama metni ekleme.

TEKNIK SARTNAME:
---
${msg.tsMetni}
---`;

node.status({ fill: "blue", shape: "dot", text: "kod yaziliyor..." });
return msg;

const kod = msg.payload.response || msg.payload;

msg.payload = kod;
msg.filename = "/internal-storage-files/cikti/03-kod.abap";

node.status({ fill: "green", shape: "dot", text: `kod yazildi (tur ${msg.tur})` });
return msg;

// Ust sinira ulasildi: zincir kendini toparlayamadi.
// Ders 7'nin "vazgec" dali ile ayni felsefe -- sessizce durma, iz birak.

const satirlar = [
  "# Insan mudahalesi gerekli",
  "",
  `Zincir ${msg.tur} turda onay alamadi.`,
  "",
  "## Reviewer ozeti",
  msg.ozet || "(ozet yok)",
  "",
  "## Kalan bulgular",
  ...(msg.bulgular || []).map(b => `- [${b.onem || "orta"}] ${b.madde}`),
  "",
  `Son teknik sartname: /internal-storage-files/cikti/02-TS-tur${msg.tur}.md`
];

msg.payload = satirlar.join("\n");
msg.filename = "/internal-storage-files/cikti/MUDAHALE-GEREKLI.md";

node.warn(["ZINCIR ONAY ALAMADI", msg.ozet]);
return msg;
